import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/31-Why-havent-self-driving-cars-become-widespread-yet.html","title":"31-别急着撒手！自动驾驶，还在路上","lang":"zh-CN","frontmatter":{"title":"31-别急着撒手！自动驾驶，还在路上","icon":"read","date":"2025-04-26T08:35:14.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":19,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"5e09f72a9f3d0e1c6b3071fd84c3809c76136d7e","time":1745649742000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"a2bcd18dbd6b8b3cefb8b96f0ab4ad5e3ac5f65d","time":1745649547000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add initial draft for \\"All artificial intelligence turns out to be very weak\\" article"},{"hash":"3f39966e91fdd041b8e2eeceab589629a9450f1f","time":1745648455000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"c877391e4d6871c8328ae6f58aa25773fbb6749f","time":1745636477000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement code changes to enhance functionality and improve performance"},{"hash":"cc73bb398e1bbd314b6e3fb01188dc4990677ec2","time":1745632346000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"e2a3665d9bcc352d0960dfda718cf1a11f06fd01","time":1745632010000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"502010d7d0aff73d748d2b1f8521f50ff8fde818","time":1745631211000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"78982cdd7701e9137da1888ef2955e8a1a3c3bac","time":1745628041000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":10.53,"words":3160},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/31-Why-havent-self-driving-cars-become-widespread-yet.md"}`),a={name:`31-Why-havent-self-driving-cars-become-widespread-yet.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>如果你喜欢科幻电影或者小说，一定对“<strong>自动驾驶汽车</strong>”不陌生。</p><p>想象一下，在正义与邪恶交锋的时刻，<strong>蝙蝠侠</strong>轻轻一点按钮，他的蝙蝠车便自动出发，把救下的人质安全送走，而他自己能专心去制服反派。更妙的是，战斗结束后，蝙蝠车还能准时出现在指定地点，把他接回家，顺便赶上晚饭。是不是酷得不行？</p><figure><img src="/assets/image-20250426085810138-B49LFgcq.png" alt="蝙蝠侠战车" tabindex="0" loading="lazy"><figcaption>蝙蝠侠战车</figcaption></figure><p>谁不想拥有这样一辆聪明又能干的汽车呢？全家出门旅行的时候，爸爸妈妈可以一边享受美食小火锅，一边欣赏窗外的风景，根本不用操心开车的辛苦。听起来是不是梦想成真？不过，别急着太开心——真正意义上的自动驾驶汽车，目前离我们还挺远的。</p><h2 id="_1-自动驾驶-人类的百年梦想" tabindex="-1"><a class="header-anchor" href="#_1-自动驾驶-人类的百年梦想"><span>1. 自动驾驶：人类的百年梦想</span></a></h2><p>说到自动驾驶的历史，可不是最近才冒出来的新鲜事。<strong>一百多年前</strong>，科学家们就已经在琢磨这件事了。只不过，受限于当时的技术水平，他们搞出来的“自动驾驶”，其实更像是“远程遥控车”，离真正的自动驾驶差得很远。</p><figure><img src="/assets/image-20250426090540930-BhxHa0tY.png" alt="有轨电车" tabindex="0" loading="lazy"><figcaption>有轨电车</figcaption></figure><p>到了<strong>1939年</strong>，人们推出了一种“有轨电车”，算是自动驾驶领域的小突破。这种电车能沿着地面轨道行驶，感知轨道上传来的电信号，从而避免追尾。可惜，它只能在固定轨道上跑，灵活性太差，远远满足不了真正上路的需求。</p><p>后来在<strong>1960年代</strong>，科学家们又想出了新招：在公路底下埋<strong>电缆</strong>，让汽车靠着电磁信号导航。这听上去不错，但想想要给每一条公路都铺上电缆，成本和麻烦程度简直爆表。科学家们于是琢磨：能不能让汽车自己“看路”呢？</p><p>到了<strong>1980年前后</strong>，随着<strong>雷达</strong>、<strong>摄像头</strong>和<strong>人工智能</strong>技术的进步，终于有了曙光。汽车可以自己用“眼睛”（雷达、摄像头）观察周围环境，再用“大脑”（人工智能）判断该怎么开。虽然一开始只能在简单环境中勉强行驶，但这已经是自动驾驶的重要飞跃。</p><h2 id="_2-那现在呢-为什么路上还是很少见" tabindex="-1"><a class="header-anchor" href="#_2-那现在呢-为什么路上还是很少见"><span>2. 那现在呢？为什么路上还是很少见？</span></a></h2><p>听到这儿你可能会问：现在科技这么发达，自动驾驶不是早该普及了吗？</p><figure><img src="/assets/image-20250426094740003-SI47YHdB.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="/assets/image-20250426094613412-CZ3_aaJY.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>确实，在<strong>矿区</strong>、<strong>码头</strong>、<strong>机场</strong>这些封闭、规则简单的环境里，自动驾驶车辆已经大显身手了。但在我们日常生活的城市道路上，真正的自动驾驶汽车依然凤毛麟角。为什么呢？关键在于，自动驾驶需要同时做好三件事：</p><ul><li><strong>感知</strong>环境</li><li><strong>分析判断</strong>情况</li><li><strong>执行</strong>正确动作</li></ul><p>先说<strong>感知</strong>：这方面自动驾驶做得很棒。雷达和摄像头能360度无死角地观察，比人眼还厉害——所以在感知上，自动驾驶汽车合格了。</p><p>再说<strong>执行</strong>：开车其实动作很有限，无非就是踩油门、刹车、打方向盘，加上几个辅助动作。让机器人执行这些并不难，而且它们在紧急情况下不会慌张，不会把油门当刹车，执行方面也 OK——所以在执行上，自动驾驶汽车也合格了，甚至比人类靠谱！</p><p>问题出在了最难的一环——<strong>分析判断</strong>，这是自动驾驶技术里最难的部分。自动驾驶汽车虽然能360度无死角地搜集信息。但在分析这些信息的时候，可能会出错。</p><p>其实在现实生活中，已经有很多汽车有自动驾驶的系统了，但它们还<strong>不能</strong>起到完全的自动驾驶功能，只能<strong>辅助</strong>人类驾驶员完成一些简单的操作。</p><p>例如：<strong>特斯拉</strong>汽车的<strong>自动巡航系统</strong>就是这样的辅助系统，接着往下阅读。</p><h2 id="_3-自动驾驶-败在哪" tabindex="-1"><a class="header-anchor" href="#_3-自动驾驶-败在哪"><span>3. 自动驾驶，败在哪？</span></a></h2><figure><img src="/assets/image-20250426100436029-CKR0tb0L.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>尽管“智能”汽车可以采集大量信息，但分析这些信息、做出正确决定，却极其复杂。有时候，仅仅因为一点点小误判，就可能引发严重事故。</p><p>举个例子：<strong>2016年</strong>，一位特斯拉车主布朗在使用<strong>自动巡航系统</strong>时，因过度依赖技术，在车上安心地看起了《哈利·波特》电影。期间，车辆发出<strong>7次</strong>警报，提醒他握好方向盘，但他没理会。</p><p>前面我们也提到了：这个系统并不是真正意义上的自动驾驶，它可能会做出一些错误的判断，所以需要人类司机在旁边辅助。</p><p>布朗之前也经常用自动巡航功能，从没出过事故。但是这次使用的结果：特斯拉误把一辆白色大货车当成了天上的白云，没有及时刹车，直接撞了上去，布朗不幸丧命。</p><p>另外，如果布朗听到警报声之后老老实实地握着方向盘看着前方，是可以发现大货车的，轻轻松松就能避开它，可惜的是，他看电影实在是太专心了，这才酿成了悲剧。</p><p>这起悲剧告诉我们：哪怕系统准确率达到了<strong>99.9%</strong>，只要有<strong>0.1%的失误</strong>，在高速行驶的汽车上，也可能是致命的。</p><p>相比之下，如果家里的扫地机器人认错，把你的珍贵的首饰吸走了，最多挨顿骂。但自动驾驶车，一次小小的分析失误，代价就是生命。</p><p>通过这个实际例子，我们可以知道自动驾驶汽车在<strong>分析判断</strong>这项能力上没能过关。</p><figure><img src="/assets/su7_1-B1KLpPVP.jpg" alt="小米 su7" tabindex="0" loading="lazy"><figcaption>小米 su7</figcaption></figure><p>前面的布朗事故算是比较早期的，也表达了：哪怕自动驾驶技术已经非常厉害了，但只要分析判断出现<strong>极小概率的失误</strong>，也可能引发重大事故。</p><p>接下来我要举一个近期的，这样的例子，最近就又发生了一起。</p><p><strong>2025年3月29日</strong>晚，一辆小米 SU7 在<strong>安徽铜陵</strong>的高速公路上，撞上了施工区的水泥隔离桩，随后起火燃烧，车上<strong>三名大学生不幸遇难</strong>。</p><p>这起事故引发了社会各界的广泛关注，大家纷纷质疑：智能驾驶系统是否可靠？车辆设计是否足够安全？施工区域的安全管理是否到位？小米公司的应对是否及时妥当？</p><figure><img src="/assets/raw-BU8a1gp3.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>根据小米公司<strong>4月1日</strong>发布的调查信息，当时车辆正在使用 <strong>NOA 智能辅助驾驶</strong>功能，以<strong>116公里/小时</strong>的速度行驶。</p><p>在施工路段，路障封闭了本车道，车辆系统检测到障碍后，立即发出了风险提示：“请注意前方有障碍。”时间是<strong>22:44:24</strong>。<br> 紧接着的<strong>一秒钟后</strong>（22:44:25），驾驶员接管了车辆，开始人工驾驶，左打方向盘约22度，同时踩下制动踏板（刹车开度31%）。<br> 但是，仅仅过了<strong>2-4秒</strong>，车辆就撞上了隔离带的水泥桩，随后发生了燃烧。</p><p>也就是说，从智能系统发出警告到撞击，仅有几秒钟的反应时间。</p><p>这起事件再次提醒我们：即使车辆拥有智能驾驶辅助，即使反应速度已经很快，但在极端、复杂、突发的环境下，人类和机器之间的配合依然可能出现短板。而这些短板，付出的代价，可能是无法挽回的生命。</p><p>这也是体现就算身处 2025 年，我们还是依然要谨慎对待自动驾驶。</p><p>（上面的例子，不带任何评论事件，仅供学习示例！）</p><h2 id="_4-拆解复杂问题-一步步来" tabindex="-1"><a class="header-anchor" href="#_4-拆解复杂问题-一步步来"><span>4. 拆解复杂问题，一步步来</span></a></h2><figure><img src="/assets/image-20250426141203639-CA-Z4Zwp.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>那么，人类就此放弃自动驾驶了吗？当然不会！</p><p>对于这种短时间里解决不了的复杂问题，科学家早就有一种应对方法，那就是<strong>拆解问题</strong>，一小步一小步地完成。（省字版：<strong>把问题拆小，逐步推进</strong>）。</p><p>既然不能一次性造出完美的自动驾驶汽车，那就先“后退一步”：造出能够应付<strong>大部分情况</strong>的自动驾驶汽车，科学家管这样的汽车叫有条件的自动驾驶汽车。</p><p>这么说估计不太好理解，我换句话来说：就是先研发出能应付<strong>大部分简单情况</strong>的自动驾驶汽车，当道路环境复杂、行人车流密集时，就交回给人类司机操控。这样的技术被称为“<strong>有条件的自动驾驶</strong>”，也就是你在新闻里常听到的版本。</p><p>这样是不是清晰很多了，所以随着有条件自动驾驶越来越普及，技术经验逐渐积累，使有条件自动驾驶技术成熟，未来实现真正的完全自动驾驶，就会容易得多。</p><h2 id="_5-拆解对于生活中的启发" tabindex="-1"><a class="header-anchor" href="#_5-拆解对于生活中的启发"><span>5. 拆解对于生活中的启发</span></a></h2><figure><img src="/assets/image-20250426141014082-fWPBQWdS.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>上面科学家使用的：把复杂问题拆分成几个阶段的做法，我们在生活中也能用到。</p><p>生活中，这种<strong>拆解大目标</strong>的思路也很实用。</p><p>比如，你想成为全年级第一，听起来压力山大，并且很可能学着学着就想放弃了。这时候你可以把这个目标<strong>拆解</strong>一下，我们可以先制定如下计划：</p><ol><li>第一步：提升薄弱学科；</li><li>第二步：总结有效学习方法，还可以向其他同学请教学习方法，总结出最适合自己的学习方法；</li><li>第三步：做好了前两个阶段，最后全力冲刺，梦想就不再那么遥不可及了。</li></ol><p>总之：我们要学会把拆解问题的思维方式，将复杂的大问题拆解小问题。当所有拆解的小问题，逐一被解决时，也会反哺大问题解决。</p><p><s><strong>总之，学会把问题拆解，大问题拆解成小问题，当所有小问题逐一被解决后，大问题也会随之迎刃而解。</strong></s></p><p>自动驾驶技术也是如此——不是一蹴而就，而是一步步解决小难题，积累经验，最终向真正的完全自动驾驶迈进。</p><h2 id="_6-自动驾驶级别的-6个等级" tabindex="-1"><a class="header-anchor" href="#_6-自动驾驶级别的-6个等级"><span>6. 自动驾驶级别的 6个等级</span></a></h2><figure><img src="/assets/sae_j3016_visual_chart_page1-Bvak_4El.png" alt="自动驾驶分级图表" tabindex="0" loading="lazy"><figcaption>自动驾驶分级图表</figcaption></figure><p>聊了这么多，可能你已经发现了：自动驾驶其实也不是一蹴而就的。为了更清楚地区分自动驾驶的发展阶段，<strong>国际汽车工程师协会（SAE）专门制定了一个标准，把自动驾驶划分成了6个等级</strong>，从L0到L5，分别对应不同的智能化程度：</p><ul><li><strong>L0级</strong>：完全没有自动驾驶功能，全靠人来开。</li><li><strong>L1级</strong>：部分辅助，比如可以自动控制方向盘或者刹车油门，但不能同时做两件事。</li><li><strong>L2级</strong>：组合辅助，方向盘和油门刹车可以同时由系统控制，但人必须随时准备接管。</li><li><strong>L3级</strong>：有条件自动驾驶，在特定环境下，车辆可以自己开，人可以暂时不接管，但遇到复杂情况仍需人来掌控。</li><li><strong>L4级</strong>：高度自动驾驶，在某些限定区域内，车辆可以完全自己开，人可以彻底放手。</li><li><strong>L5级</strong>：完全自动驾驶，无论什么环境，什么路况，车辆都能自主行驶，根本不需要人来操心。</li></ul><p>目前我们最常听到的“自动驾驶”，大多数其实还是处在 <strong>L2 到 L3</strong>阶段，真正意义上的 L5 完全自动驾驶，还在未来等着我们去实现。</p>`,64)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};